const { name, workspaceGid, projectGid, assignee, notes, htmlNotes, dueOn, tags } = $.input;

if (!name || !workspaceGid) throw new Error('name and workspaceGid are required');

const data = {
  data: {
    name,
    workspace: workspaceGid
  }
};

if (projectGid) data.data.projects = [projectGid];
if (assignee) data.data.assignee = assignee;
if (htmlNotes) {
  data.data.html_notes = htmlNotes;
} else if (notes) {
  data.data.notes = notes;
}
if (dueOn) data.data.due_on = dueOn;
if (tags && tags.length > 0) data.data.tags = tags;

return data;

const task = $.steps.createTask.response?.data || {};
const sectionResult = $.steps.addToSection?.response || null;

return {
  taskGid: task.gid || '',
  name: task.name || '',
  assignee: task.assignee ? (task.assignee.name || task.assignee.gid) : 'unassigned',
  dueOn: task.due_on || null,
  projectGid: $.input.projectGid || null,
  sectionGid: $.input.sectionGid || null,
  movedToSection: !!sectionResult,
  permalink: task.permalink_url || '',
  summary: `Created task "${task.name || $.input.name}"${task.assignee ? ' assigned to ' + (task.assignee.name || task.assignee.gid) : ''}${task.due_on ? ' due ' + task.due_on : ''}`
};
